function rightTriangles(n: number): number {
  let count = 0;
  for (let a = 1; a <= n; a++) {
    for (let b = 1; b <= n; b++) {
      const s = a * a + b * b;
      const c = Math.round(Math.sqrt(s));
      if (c <= n && c * c === s) count++;
    }
  }
  return count;
}

